package example.rnl8;

class C { String m(int a) { return String.format("""
            %d
            """, a); } }

package example.slf8;

import org.slf4j.*;

class C {
    private static final Logger log = LoggerFactory.getLogger(C.class);

    void m(int a) {
        if (log.isDebugEnabled()) {
            log.info("a {}", a);
        }
    }
}

package example.slf11;

import org.slf4j.*;

class C {
    private static final Logger log = LoggerFactory.getLogger(C.class);

    void m(int a) {
        if (log.isInfoEnabled()) {
            log.info("a {}", a);
        }
    }
}
